  defs['offline'] = function (module, exports, require) {
// Offline analyzer: matches Chinese sentences to the curated bank. No network needed.
'use strict';
const { VOCAB, GRAMMAR, SENTENCES } = require('./bank');

function splitZh(text) {
  return String(text || '')
    .replace(/\s+/g, ' ')
    .split(/(?<=[。！？!?；;\n])/)
    .map(s => s.trim())
    .filter(s => s.replace(/[。！？!?；;，,\s]/g, '').length > 0);
}

function bigrams(s) {
  const t = s.replace(/[\s。！？!?，,、；;：:“”"'（）()]/g, '');
  const set = new Set();
  for (let i = 0; i < t.length - 1; i++) set.add(t.slice(i, i + 2));
  return set;
}

function similarity(a, b) {
  const A = bigrams(a), B = bigrams(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const x of A) if (B.has(x)) inter++;
  return inter / Math.min(A.size, B.size) * 0.5 + inter / Math.max(A.size, B.size) * 0.5;
}

function nums(s) { return (s.match(/\d+(?:\.\d+)?/g) || []); }

function toHalfDigits(s) {
  return s.replace(/[０-９．％]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0));
}

function matchSentence(zh) {
  const z = toHalfDigits(zh);
  let best = null;
  for (const s of SENTENCES) {
    const sim = similarity(z, s.zh);
    let kwHits = 0;
    for (const k of s.kw) if (z.includes(k)) kwHits++;
    const score = sim * 0.6 + Math.min(kwHits / Math.max(3, s.kw.length * 0.6), 1) * 0.4;
    if (!best || score > best.score) best = { s, score, sim };
  }
  if (!best || best.score < 0.28) return null;
  let { ja, kana } = best.s;
  // Substitute numbers in order when the counts line up (e.g. 95% -> 90%).
  const un = nums(z), bn = nums(best.s.zh);
  if (un.length && un.length === bn.length) {
    let i = 0, j = 0;
    ja = ja.replace(/\d+(?:\.\d+)?/g, m => (bn.includes(m) ? un[i++] ?? m : m));
    kana = kana.replace(/\d+(?:\.\d+)?/g, m => (bn.includes(m) ? un[j++] ?? m : m));
  }
  return { zh, ja, kana, bank_zh: best.s.zh, confidence: best.sim > 0.75 ? 'exact' : 'approx' };
}

// Longest-first glossary scan over Japanese text, so 根本原因 wins over 原因.
function extractVocab(jaText) {
  const sorted = [...VOCAB].sort((a, b) => b.ja.length - a.ja.length);
  let masked = jaText;
  const found = [];
  for (const v of sorted) {
    if (masked.includes(v.ja)) {
      found.push({ ja: v.ja, kana: v.kana, zh: v.zh[0], pos: jaText.indexOf(v.ja) });
      masked = masked.split(v.ja).join('□'.repeat(v.ja.length));
    }
  }
  return found.sort((a, b) => a.pos - b.pos).map(({ pos, ...r }) => r);
}

function extractGrammar(jaText) {
  const out = [];
  for (const g of GRAMMAR) {
    const m = g.match.find(x => jaText.includes(x));
    if (m) out.push({ pattern: g.pattern, match: m, zh: g.zh, example_ja: g.example_ja, example_kana: g.example_kana, example_zh: g.example_zh, pos: jaText.indexOf(m) });
  }
  return out.sort((a, b) => a.pos - b.pos).map(({ pos, ...r }) => r);
}

// Chinese-side vocab hits for sentences the bank could not translate.
function zhVocabHits(zh) {
  const out = [];
  for (const v of VOCAB) if (v.zh.some(a => a.length >= 2 && zh.includes(a))) out.push({ ja: v.ja, kana: v.kana, zh: v.zh[0] });
  return out;
}

function analyzeOffline(text) {
  const parts = splitZh(text);
  const sentences = [], unmatched = [];
  for (const p of parts) {
    const clauses = p.split(/(?<=[，,])/).map(x => x.trim()).filter(x => x.replace(/[，,。！？!?\s]/g, '').length > 1);
    let used = false;
    if (clauses.length > 1) {
      const ms = [];
      for (const c of clauses) {
        const m = matchSentence(c);
        if (m && (!ms.length || ms[ms.length - 1].bank_zh !== m.bank_zh)) ms.push(m);
        else if (m) ms[ms.length - 1].zh += c;
        else if (c.replace(/[，,。\s]/g, '').length > 4) unmatched.push(c);
      }
      if (ms.length > 1) { sentences.push(...ms); used = true; }
      else if (ms.length === 1) { const whole = matchSentence(p); sentences.push(whole && whole.bank_zh !== ms[0].bank_zh ? whole : ms[0]); used = true; }
    }
    if (!used) { const m = matchSentence(p); if (m) sentences.push(m); else unmatched.push(p); }
  }
  const jaAll = sentences.map(s => s.ja).join('');
  const vocab = extractVocab(jaAll);
  for (const u of unmatched) for (const v of zhVocabHits(u)) if (!vocab.find(x => x.ja === v.ja)) vocab.push(v);
  const grammar = extractGrammar(jaAll);
  const tips = ['会议中说自己的动作用谦让语（〜させていただきます／いたします／ご報告）。', '汇报现状用「〜ております」，推测用「〜可能性がございます」「〜と考えております」，避免说得太绝对。'];
  if (sentences.some(s => s.confidence === 'approx')) tips.unshift('离线模式：部分句子是按意思匹配到最接近的标准会议句，不是逐字翻译，请对照原句看。');
  return { mode: 'offline', sentences, vocab, grammar, tips, unmatched };
}

module.exports = { analyzeOffline, extractVocab, extractGrammar, splitZh };

};
  defs['llm'] = function (module, exports, require) {
// Pluggable LLM provider (any OpenAI-compatible /chat/completions endpoint).
// Reads LLM_API_KEY / LLM_BASE_URL / LLM_MODEL from the environment or config/llm.env,
// re-read on every call so a key can be added without restarting the server.
'use strict';
const { extractVocab, extractGrammar } = require('./offline');

// Server only (Node): env vars + config/llm.env
function loadLlmConfig(settings) {
  const fs = require('fs'), path = require('path');
  const ENV_FILE = path.join(__dirname, '..', '..', 'config', 'llm.env');
  const fileVars = {};
  try {
    for (const line of fs.readFileSync(ENV_FILE, 'utf8').split('\n')) {
      const m = line.match(/^\s*([A-Z_]+)\s*=\s*(.*?)\s*$/);
      if (m && !m[1].startsWith('#')) fileVars[m[1]] = m[2].replace(/^["']|["']$/g, '');
    }
  } catch (_) { /* no file */ }
  const get = k => process.env[k] || fileVars[k] || '';
  const c = settings.llm || {};
  return {
    apiKey: get(c.api_key_env || 'LLM_API_KEY'),
    baseUrl: (get(c.base_url_env || 'LLM_BASE_URL') || c.default_base_url || 'https://api.openai.com/v1').replace(/\/+$/, ''),
    model: get(c.model_env || 'LLM_MODEL') || c.default_model || 'gpt-4o-mini',
  };
}

const SYSTEM = `你是日本半导体企业的资深口译兼商务日语老师。用户会给一段中文（通常是半导体工厂/会议里的发言）。
任务：把它转述成自然、得体的日本商务会议日语（です・ます体为主，对自己的动作用谦让语，如「〜させていただきます」「いたします」「ご報告いたします」，汇报现状用「〜ております」）。使用半导体行业惯用词（歩留まり、不良率、工程、前工程/後工程、ウェハ、ロット、量産、納期、装置、エッチング、露光、洗浄、パーティクル、対策、検討 等），不要用旅游口语。
只输出 JSON，结构：
{"sentences":[{"zh":"对应的中文原句","ja":"日语句子","kana":"整句的平假名读音（外来语也写成平假名，数字和%保持原样，标点保留）"}],
 "vocab":[{"ja":"词（必须原样出现在某个 ja 句子里）","kana":"平假名读音","zh":"中文意思","note":"可选，简短用法说明"}],
 "grammar":[{"pattern":"句型，如 〜させていただきます","match":"该句型在 ja 句子中原样出现的片段","zh":"中文解释（为什么这样说、敬语层级）","example_ja":"另一个半导体会议例句","example_kana":"例句平假名","example_zh":"例句中文"}],
 "tips":["1-3 条中文提示：敬语/会议表达要点"]}
要求：按原文顺序逐句对应；vocab 挑 5-12 个对会议最有用的词（专业词、商务词优先）；grammar 挑 3-8 个句型；kana 必须准确。`;

async function analyzeWithLlm(text, settings) {
  return analyzeWithConfig(text, loadLlmConfig(settings));
}

// Works in Node 18+ and in the browser (cfg = {apiKey, baseUrl, model}).
async function analyzeWithConfig(text, cfg) {
  if (!cfg.apiKey) throw new Error('NO_KEY');
  const body = {
    model: cfg.model,
    temperature: 0.2,
    messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: String(text).slice(0, 2000) }],
    response_format: { type: 'json_object' },
  };
  const call = async (b) => {
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), 60000);
    try {
      const r = await fetch(cfg.baseUrl + '/chat/completions', {
        method: 'POST', signal: ctl.signal,
        headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + cfg.apiKey },
        body: JSON.stringify(b),
      });
      const txt = await r.text();
      if (!r.ok) { const e = new Error('LLM_HTTP_' + r.status); e.detail = txt.slice(0, 300); throw e; }
      return JSON.parse(txt);
    } finally { clearTimeout(t); }
  };
  let resp;
  try { resp = await call(body); }
  catch (e) {
    if (/LLM_HTTP_4\d\d/.test(e.message) && !/40[13]/.test(e.message)) { delete body.response_format; resp = await call(body); }
    else throw e;
  }
  let content = resp.choices?.[0]?.message?.content || '';
  content = content.replace(/^```(?:json)?/m, '').replace(/```\s*$/m, '');
  const s = content.indexOf('{'), en = content.lastIndexOf('}');
  const data = JSON.parse(content.slice(s, en + 1));
  return normalize(data);
}

function normalize(d) {
  const sentences = (d.sentences || []).filter(x => x && x.ja).map(x => ({ zh: String(x.zh || ''), ja: String(x.ja), kana: String(x.kana || '') }));
  if (!sentences.length) throw new Error('LLM_EMPTY');
  const jaAll = sentences.map(x => x.ja).join('');
  let vocab = (d.vocab || []).filter(v => v && v.ja).map(v => ({ ja: String(v.ja), kana: String(v.kana || ''), zh: String(v.zh || ''), note: v.note ? String(v.note) : undefined }));
  for (const v of extractVocab(jaAll)) if (!vocab.find(x => x.ja === v.ja) && vocab.length < 14) vocab.push(v);
  let grammar = (d.grammar || []).filter(g => g && g.pattern).map(g => ({
    pattern: String(g.pattern), match: String(g.match || ''), zh: String(g.zh || ''),
    example_ja: String(g.example_ja || ''), example_kana: String(g.example_kana || ''), example_zh: String(g.example_zh || ''),
  }));
  if (!grammar.length) grammar = extractGrammar(jaAll);
  return { mode: 'ai', sentences, vocab, grammar, tips: (d.tips || []).map(String).slice(0, 4), unmatched: [] };
}

module.exports = { analyzeWithLlm, analyzeWithConfig, loadLlmConfig, SYSTEM };

};
